function validate([strength]) {
  if (strength.length < 1 || strength.length > 80) return 'strength needs 1 to 80 locks.';
  if (strength.some(s => s < 1 || s > 1000000)) return 'Each strength is between 1 and 10^6.';
  return null;
}

