function findMinimumTime(strength) {
  const n = strength.length;
  const cost = (lock, turn) => Math.ceil(strength[lock - 1] / turn);
  const lockPotential = new Array(n + 1).fill(0);
  const turnPotential = new Array(n + 1).fill(0);
  const owner = new Array(n + 1).fill(0);
  const cameFrom = new Array(n + 1).fill(0);
  for (let lock = 1; lock <= n; lock++) {
    owner[0] = lock;
    let turn = 0;
    const minSlack = new Array(n + 1).fill(Infinity);
    const visited = new Array(n + 1).fill(false);
    while (owner[turn] !== 0) {
      visited[turn] = true;
      const current = owner[turn];
      let delta = Infinity;
      let nextTurn = 0;
      for (let j = 1; j <= n; j++) {
        if (visited[j]) continue;
        const slack = cost(current, j) - lockPotential[current] - turnPotential[j];
        if (slack < minSlack[j]) {
          minSlack[j] = slack;
          cameFrom[j] = turn;
        }
        if (minSlack[j] < delta) {
          delta = minSlack[j];
          nextTurn = j;
        }
      }
      for (let j = 0; j <= n; j++) {
        if (visited[j]) {
          lockPotential[owner[j]] += delta;
          turnPotential[j] -= delta;
        } else {
          minSlack[j] -= delta;
        }
      }
      turn = nextTurn;
    }
    while (turn !== 0) {
      const previous = cameFrom[turn];
      owner[turn] = owner[previous];
      turn = previous;
    }
  }
  let total = 0;
  for (let turn = 1; turn <= n; turn++) {
    total += cost(owner[turn], turn);
  }
  return total;
}

