function findMinimumTime(strength) {
  // best[mask]: fewest minutes to break exactly the locks in mask; the next lock then uses factor |mask| + 1.
  const n = strength.length;
  const best = new Array(1 << n).fill(Infinity);
  best[0] = 0;
  for (let mask = 0; mask < (1 << n); mask++) {
    if (best[mask] === Infinity) continue;
    let factor = 1;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) factor++;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) continue;
      const minutes = Math.floor((strength[i] + factor - 1) / factor);
      const next = mask | (1 << i);
      best[next] = Math.min(best[next], best[mask] + minutes);
    }
  }
  return best[(1 << n) - 1];
}

