function generate(rand, size) {
  const n = size === 'large' ? 80 : 1 + Math.floor(rand() * 8);
  // Small strengths make many rounded costs tie; large ones spread them out.
  const shape = rand();
  const top = shape < 0.35 ? 12 : shape < 0.7 ? 300 : 1000000;
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
